let personalised=true,mode='live',demoDismissed=false,demoAlert=null;
try{mode=localStorage.getItem('margin-mode')==='demo'?'demo':'live';demoDismissed=localStorage.getItem('margin-demo-dismissed')==='1';const alert=localStorage.getItem('margin-demo-alert');demoAlert=['publicBus','shuttle'].includes(alert)?alert:null;}catch{}
try{
 const saved=JSON.parse(localStorage.getItem('margin-routine')||'null'),collection=JSON.parse(localStorage.getItem('margin-routines')||'null');
 if(Array.isArray(collection?.items)&&collection.items.length){personalised=localStorage.getItem('margin-personalised')!=='0';routines=collection.items;activeRoutineId=collection.activeId||routines[0].id;const active=routines.find(item=>item.id===activeRoutineId)||routines[0];state={...state,...active.state};activeRoutineId=active.id;}
 else {state={...state,...saved};if(!saved)personalised=false;activeRoutineId='routine-1';routines=[{id:activeRoutineId,name:'Work commute',enabled:true,weekdays:[1,2,3,4,5],state:{...state}}];}
 planJourney(state);
}catch{state={...defaults};activeRoutineId='routine-1';routines=[{id:activeRoutineId,name:'Work commute',enabled:true,weekdays:[1,2,3,4,5],state:{...state}}];}
let plan,selected,zoom=1,toastTimer,gpsFix=null,gpsCandidate=null,gpsRequest=0,pickerField='origin',checkedMode=null;
let addresses={origin:null,destination:null},accessLegs={};const modal=$('#modal');
let liveRequest=0;
const escape=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
// One label style for every piece of data: live (green), estimated or forecast (grey), simulated (amber).
const badge=(kind,text)=>`<span class="data-badge ${kind}">${escape(text)}</span>`;
function save(){try{const active=routines.find(item=>item.id===activeRoutineId);if(active)active.state=Object.fromEntries(stateKeys.map(key=>[key,state[key]]));localStorage.setItem('margin-routine',JSON.stringify(state));localStorage.setItem('margin-routines',JSON.stringify({activeId:activeRoutineId,items:routines}));localStorage.setItem('margin-personalised',personalised?'1':'0');}catch{toast('Storage unavailable. Your routines will last for this session.');}}
function toast(s){$('#toast').textContent=s;$('#toast').classList.remove('hidden');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.add('hidden'),3500);}
function showModal(title,html,eyebrow='A LITTLE MORE CONTEXT'){ $('#modal-content').innerHTML=`<h2 id="dialog-title">${title}</h2>${html}`;$('#modal-eyebrow').textContent=eyebrow;if(!modal.open)modal.showModal();}
function currentRoute(){return plan.routes.find(r=>r.id===selected)||plan.best;}
// Live mode always plans normal service; the remembered scenario applies only in Demo mode.
function plannedState(){return mode==='live'||demoAlert?{...state,scenario:'normal'}:state;}
function setMode(next){mode=next;try{localStorage.setItem('margin-mode',next);}catch{}checkedMode=null;liveRequest++;}
function useDemo(alert=null){setMode('demo');demoAlert=alert;try{alert?localStorage.setItem('margin-demo-alert',alert):localStorage.removeItem('margin-demo-alert');}catch{}}
// Both Live mode and the free-travel demos wait for an alert check before the recommendation is shown.
function needsCheck(){return mode==='live'||Boolean(demoAlert);}
function decisionTag(){if(mode==='demo')return checkedMode?.source==='live'?'LIVE LTA CHECK':'SIMULATED';if(!checkedMode)return 'LIVE';if(checkedMode.source==='unavailable')return 'LIVE UNAVAILABLE';if(checkedMode.source!=='live')return 'SIMULATED';const time=checkedTime(checkedMode.fetchedAt);return time?`LIVE · ${time}`:'LIVE';}
function decisionKind(){const tag=decisionTag();return tag==='SIMULATED'?'sim':tag==='LIVE UNAVAILABLE'?'est':'live';}
function serviceDemo(){if(mode!=='demo')return null;if(demoAlert)return {kind:'alert',data:checkedMode?.alerts||null,impacted:checkedMode?.impacted,caption:alertChips[demoAlert].caption};const s=scenarios[state.scenario];return {kind:'scenario',key:state.scenario,name:s.name,description:s.description};}
// Live mode shows only LTA's crowd forecast (or says there is none); Demo mode shows the scenario's simulated crowding.
function crowdText(route){const forecast=route.crowdObservations?.filter(item=>item.source==='forecast');if(forecast?.length)return `${forecast.map(item=>`${escape(item.stationName)}: ${escape(item.level)}`).join(' · ')} ${badge('est','LTA forecast')}`;if(mode==='live')return escape(route.crowdObservations?.[0]?.label||'No LTA crowd forecast');return `${{low:'Room to breathe',medium:'Some standing',high:'Likely crowded'}[route.crowd]} ${badge('sim','Simulated')}`;}
function crowdClass(route){const levels=route.crowdObservations?.filter(item=>item.source==='forecast').map(item=>item.level);if(levels?.length)return levels.includes('High')?'high':levels.includes('Moderate')?'medium':'low';return mode==='live'?'none':route.crowd;}
function fillForm(){for(const key of ['origin','destination','deadline','departure','threshold','priority','walkBreak'])$('#'+key).value=state[key];$('#comfort').checked=state.comfort;$('#large-text').checked=state.large;const active=routines.find(item=>item.id===activeRoutineId);if(active){$('#routine-name').value=active.name;$('#routine-enabled').checked=active.enabled;$$('[data-weekday]').forEach(box=>box.checked=active.weekdays.includes(Number(box.dataset.weekday)));}document.body.classList.toggle('large-text',state.large);renderRoutineList();renderAccessChecklist();renderNotificationStatus();}
function renderRoutineList(){const host=$('#routine-list');if(!host)return;const days=['Mon','Tue','Wed','Thu','Fri','Sat','Sun'];host.innerHTML=routines.map(item=>`<button type="button" class="routine-card ${item.id===activeRoutineId?'active':''}" data-routine-id="${escape(item.id)}"><span><strong>${escape(item.name)}</strong><small>${escape(places[item.state.origin]?.name||item.state.origin)} → ${escape(places[item.state.destination]?.name||item.state.destination)} · ${item.state.departure} · ${item.weekdays.map(day=>days[day-1]).join(', ')||'No days'}</small></span><span class="routine-state">${item.enabled?'ON':'OFF'}</span></button>`).join('');$('#delete-routine').disabled=routines.length===1;}
const accessItems=[['originExit','Correct origin entrance and exit'],['stepFree','Lifts or step-free path available'],['crossings','Crossings and pavements usable'],['shelter','Shelter and lighting acceptable'],['destinationExit','Correct destination exit'],['timing','Walking time checked on foot']];
function accessKey(){return `margin-access-${activeRoutineId}`;}
function renderAccessChecklist(){const host=$('#access-checklist');if(!host)return;let saved={};try{saved=JSON.parse(localStorage.getItem(accessKey())||'{}');}catch{}host.innerHTML=`<p><strong>${escape(places[state.origin]?.name)} → ${escape(places[state.destination]?.name)}</strong></p>${accessItems.map(([id,label])=>`<label class="checkbox-label"><input type="checkbox" data-access-check="${id}" ${saved[id]?'checked':''}>${label}</label>`).join('')}<p><small>${Object.values(saved).filter(Boolean).length}/${accessItems.length} confirmed. A routing API cannot verify these physical conditions.</small></p>`;}
function renderNotificationStatus(){const out=$('#notification-status');if(!out)return;const supported='Notification'in window&&'serviceWorker'in navigator;out.textContent=!supported?'Notifications are unavailable in this browser.':Notification.permission==='granted'?'Alerts are enabled. Margin asks supported installed browsers to check periodically; delivery timing is controlled by the browser.':Notification.permission==='denied'?'Notifications are blocked in browser settings.':'Enable notifications to receive disruption checks where your installed browser supports background sync.';$('#test-notification').disabled=!supported||Notification.permission!=='granted';}
// Route card: what the route is best at, when it gets you there and how much spare time that leaves, then the trade-off.
function routeCard(r,info,recommended){
 const t=tripSummary(plan,r,{departure:state.departure,deadline:state.deadline,threshold:state.threshold});
 return `<button class="route-card ${r.id===selected?'selected':''}" data-route="${r.id}" aria-pressed="${r.id===selected}"><div class="route-top"><span class="route-name"><span class="radio"></span><span class="route-title"><span class="route-label">${escape(info.label)}</span>${recommended?'<span class="recommend-tag">Recommended</span>':''}</span></span><span class="route-arrive"><strong>Arrive ${t.latest}</strong><span class="route-spare" data-tone="${t.tone}">${t.spare}</span></span></div><div class="route-chain"><span class="walk">Walk</span><span>›</span>${r.lines.map(l=>l==='walk'?'<span class="walk">Walk</span>':`<span class="line-badge ${l.toLowerCase()}">${l}</span>`).join('<span>›</span>')}<span>›</span><span class="walk">Walk</span></div><p class="route-facts">${changesText(r.transfers)} · ${r.min}–${r.max} min · ${r.walk} min walking${r.delay?` · <span class="delay-tag">+${r.delay} min delay</span>`:''}</p>${info.compare?`<p class="route-compare">${escape(info.compare)}</p>`:''}<div class="route-meta"><span class="crowd"><span class="crowd-bars ${crowdClass(r)}"><i></i><i></i><i></i></span>${crowdText(r)}</span></div></button>`;
}
function decisionCopy(loading,r){if(loading)return '';if(checkedMode)return checkedMode.detail||'';if(r.buffer<0)return '';if(plan.usual.delay)return r.id==='usual'?'The simulated delay still leaves you enough time.':'Rerouted around the simulated disruption below.';return '';}
// The trip card as a timeline: leave → travel → latest arrival → spare time → deadline, plus a one-line verdict.
function renderTripCard(r,loading){
 const dash='–',t=tripSummary(plan,r,{departure:state.departure,deadline:state.deadline,threshold:state.threshold}),tone=loading?'wait':t.tone;
 $('#trip-day').textContent=mode==='live'?tripDay(state.departure):'Demo trip';$('#trip-route').textContent=`${places[state.origin].name} → ${places[state.destination].name}`;
 const verdict=$('#trip-verdict');verdict.dataset.tone=tone;verdict.querySelector('.verdict-icon').textContent=loading?'…':{ok:'✓',tight:'!',late:'✕'}[t.tone];verdict.querySelector('.verdict-text').textContent=loading?'Checking your arrival…':t.verdict;
 $('#tl-leave').textContent=t.leave;$('#tl-duration').textContent=loading?dash:t.duration;$('#tl-latest').textContent=loading?dash:t.latest;$('#tl-earliest').textContent=loading?'':`earliest ${t.earliest}`;
 $('#tl-spare').textContent=loading?dash:t.spare;$('#tl-spare-link').dataset.tone=tone;$('#tl-deadline').textContent=t.deadline;$('#arrival-summary').innerHTML=badge('est','Estimated times');
}
function render(reset=true,override=null){plan=override||(checkedMode&&!reset&&plan?plan:null)||applyAccessLegs(planJourney({...plannedState(),originLocation:gpsFix}),{...accessLegs,originStationName:places[state.origin].name,destinationLabel:addresses.destination?.label||places[state.destination].name});if(reset)selected=plan.best.id;const route=currentRoute();const recommended=plan.best;const loading=needsCheck()&&!checkedMode;$('.decision-card').classList.toggle('is-loading',loading);$('.decision-card').setAttribute('aria-busy',String(loading));$('#scenario-label').textContent=decisionTag();$('#scenario-label').className=`data-badge ${decisionKind()}`;$('#decision-title').textContent=loading?(mode==='live'?'Checking live conditions…':'Loading the simulated alert…'):checkedMode?checkedMode.headline:recommended.buffer<0?`Leave by ${formatTime(plan.latestLeave)} to arrive by ${state.deadline}.`:recommended.id==='usual'?`Leave as usual at ${state.departure}.`:`Leave at ${state.departure}. Take ${recommended.lines.join(' → ')}.`;$('#decision-copy').textContent=decisionCopy(loading,recommended);$('#route-count').innerHTML=`${plan.routes.length} route${plan.routes.length===1?'':'s'} · ${badge('est','Estimated times')}`;
 renderTripCard(recommended,loading);
 const described=describeRoutes(plan);
 $('#route-list').innerHTML=[...plan.routes].sort((a,b)=>(a.id===recommended.id?-1:b.id===recommended.id?1:a.arrival-b.arrival)).map(r=>routeCard(r,described[r.id],r.id===recommended.id)).join('');
 $('#weather-title').textContent=mode==='live'?'Check the weather':plan.event.rain?'A little rain ahead':'A brighter start';$('#weather-copy').textContent=mode==='live'?'Tap for the NEA 2-hour forecast':plan.event.rain?'Simulated weather · bring an umbrella':'Simulated weather · dry walking legs';$('#leave-label').textContent=`LEAVE AT ${state.departure}`;$('#step-preview').innerHTML=route.steps.slice(0,3).map((s,i)=>stepHtml(s,i)).join('');drawMap();renderMobileSummary();renderScenarioChips();mountServiceCheck({state,plan,places,onActivate:activateCheckedJourney,onRefresh:()=>{checkedMode=null;render();},originLocation:gpsFix,mode,demo:serviceDemo(),ready:!loading});if(loading&&!override)runCheck();
 $('#weather-info .overline').innerHTML=`OUTSIDE, RIGHT NOW ${mode==='demo'?badge('sim','Simulated'):''}`;$('#map-badge').innerHTML=mode==='demo'?badge('sim','Simulated'):plan.checkedAffectedEdges?.length?badge('live','Live alert'):'';
 $('#demo-banner').classList.toggle('hidden',mode!=='demo'||demoDismissed);const pill=$('#demo-info');pill.textContent=mode==='live'?'● LIVE':'DEMO';pill.dataset.mode=mode;pill.setAttribute('aria-label',mode==='live'?'Live mode. Switch to demo mode':'Demo mode. Switch to live mode');}
function checkedCopy(result,alerts){
 const r=result.plan.best;
 const headline=result.status==='no-alternative'?'Check with station staff before you board.':r.buffer<0?`Leave by ${formatTime(result.plan.latestLeave)} to arrive by ${state.deadline}.`:result.status==='clear'&&r.id==='usual'?`Leave as usual at ${state.departure}.`:`Leave at ${state.departure}. Take ${r.lines.join(' → ')}.`;
 // The disruption itself is explained by the component under the card; the card only says what Margin did about it.
 const detail=result.status==='rerouted'?'Rerouted around the disruption below.':result.status==='no-alternative'?'No rail alternative was found. See the free travel options below.':'';
 return {headline,detail};
}
// Live mode checks the official LTA alerts; the free-travel demo chips run a simulated alert through the same route logic.
// Simulated alerts never borrow live crowd readings, so each screen shows one source.
async function runCheck(){
 const request=++liveRequest,checkMode=mode,checkAlert=demoAlert;
 const stale=()=>request!==liveRequest||mode!==checkMode||demoAlert!==checkAlert||checkedMode;
 const alerts=checkMode==='live'?await fetchAlerts():{source:'demo',...parseAlerts(assistanceDemos[checkAlert])};if(stale())return;
 let result=null;
 if(['live','demo'].includes(alerts.source)){try{result=await buildCheckedPlan({state,places,alerts,originLocation:gpsFix,crowdFeedsFor:alerts.source==='live'?fetchCrowdFeeds:async()=>[]});}catch{}}
 if(stale())return;
 if(!result){checkedMode={source:'unavailable',headline:`Leave at ${state.departure}, but check station displays.`,detail:'Live LTA alerts are unavailable, so this assumes normal service.'};render(false,plan);return;}
 checkedMode={source:alerts.source,status:result.status,impacted:result.impacts.length>0,fetchedAt:alerts.fetchedAt,alerts,...checkedCopy(result,alerts)};
 plan=applyAccessLegs(result.plan,{...accessLegs,originStationName:places[state.origin].name,destinationLabel:addresses.destination?.label||places[state.destination].name});selected=plan.best.id;render(false,plan);
}
function activateCheckedJourney(next,meta){checkedMode=meta;plan=applyAccessLegs(next,{...accessLegs,originStationName:places[state.origin].name,destinationLabel:addresses.destination?.label||places[state.destination].name});selected=plan.best.id;render(false,plan);showMap(true);toast('Checked route applied to your map and journey steps.');}
function stepHtml(s,i){return `<div class="step-row"><span class="step-number">${i+1}</span><div><strong>${s.title}</strong><p>${s.detail}</p></div><span>${s.minutes} min</span></div>`;}
let mapBounds={minLon:103.82,maxLon:103.96,minLat:1.26,maxLat:1.38},roadData=[];
const lineColors={NSL:'#cf4552',EWL:'#38845c',CGL:'#38845c',NEL:'#9354b8',CCL:'#c28a1f',DTL:'#3674cd',TEL:'#8b6550',BPL:'#74845b',SLRT:'#778758',PLRT:'#778758'};
function project([lon,lat]){return [65+(lon-mapBounds.minLon)/(mapBounds.maxLon-mapBounds.minLon)*770,65+(mapBounds.maxLat-lat)/(mapBounds.maxLat-mapBounds.minLat)*460];}
function path(points){return points.map((p,i)=>`${i?'L':'M'}${project(p).map(v=>v.toFixed(1)).join(',')}`).join(' ');}
function drawMap(){if(!plan)return;const route=currentRoute(),original=plan.originalUsual||plan.usual,points=[...route.geometry,...original.geometry];let minLon=Math.min(...points.map(p=>p[0])),maxLon=Math.max(...points.map(p=>p[0])),minLat=Math.min(...points.map(p=>p[1])),maxLat=Math.max(...points.map(p=>p[1]));const centerLon=(minLon+maxLon)/2,centerLat=(minLat+maxLat)/2,lonSpan=Math.max(.035,maxLon-minLon)*1.22,latSpan=Math.max(.025,maxLat-minLat)*1.25;mapBounds={minLon:centerLon-lonSpan/2,maxLon:centerLon+lonSpan/2,minLat:centerLat-latSpan/2,maxLat:centerLat+latSpan/2};
 $('#geography').innerHTML=roadData.map(e=>`<path d="${path(e.geometry.map(p=>[p.lon,p.lat]))}" fill="none" stroke="#dce4d7" stroke-width="1.5"/>`).join('')+network.edges.filter((_,i)=>i%2===0).map(e=>`<path d="${path([places[e.from].coord,places[e.to].coord])}" fill="none" stroke="${lineColors[e.line]}" stroke-width="1.5" opacity=".25"/>`).join('');
 let html=`<path d="${path(original.geometry)}" fill="none" stroke="#759982" stroke-width="5" stroke-dasharray="7 7"/>`;
 html+=`<path d="${path(route.geometry)}" fill="none" stroke="white" stroke-width="10" stroke-linejoin="round"/><path d="${path(route.geometry)}" fill="none" stroke="#4d7bd3" stroke-width="5" stroke-linecap="round" stroke-linejoin="round"/>`;
 const affectedEdges=plan.checkedAffectedEdges||((plan.event.delay)?affectedPairs.map(([a,b])=>({from:a,to:b})):[]);for(const edge of affectedEdges)html+=`<path d="${path([places[edge.from].coord,places[edge.to].coord])}" fill="none" stroke="#c9715a" stroke-width="7" stroke-dasharray="5 3"/>`;
 const important=new Set([state.origin,state.destination,...route.edges.filter((e,i)=>i&&e.line!==route.edges[i-1].line).map(e=>e.from)]);let labels='';for(const id of route.stationIds){const[x,y]=project(places[id].coord);html+=`<circle cx="${x}" cy="${y}" r="${important.has(id)?8:4}" fill="white" stroke="#4d7bd3" stroke-width="3"/>`;if(important.has(id)){const label=places[id].name,w=Math.max(80,label.length*8+18),lx=Math.max(w/2+4,Math.min(896-w/2,x));labels+=`<rect x="${lx-w/2}" y="${y-38}" width="${w}" height="25" rx="5" fill="white"/><text x="${lx}" y="${y-21}" text-anchor="middle" fill="#294b40" font-size="13" font-family="system-ui" font-weight="600">${escape(label)}</text>`;}}
 if(gpsFix){const[x,y]=project(gpsFix.coord);html+=`<circle cx="${x}" cy="${y}" r="10" fill="#173f35" stroke="white" stroke-width="3"/>`;labels+=`<text x="${x}" y="${y+27}" text-anchor="middle" font-size="13" fill="#173f35">GPS start</text>`;}
 $('#map-routes').innerHTML=html;$('#map-labels').innerHTML=labels;}
async function loadMap(){try{const response=await fetch('/data/osm-roads.json');if(!response.ok)throw Error();const data=await response.json();roadData=data.elements.filter(e=>e.geometry);drawMap();}catch{roadData=[];drawMap();}}
$('#journey-form').addEventListener('submit',e=>{e.preventDefault();checkedMode=null;state.origin=$('#origin').value;state.destination=$('#destination').value;state.deadline=$('#deadline').value;personalised=true;save();render();toast('Your routes have been rebalanced.');});
$('#route-list').addEventListener('click',e=>{const b=e.target.closest('[data-route]');if(b){selected=b.dataset.route;render(false);}});
$$('[data-view]').forEach(b=>b.addEventListener('click',()=>switchView(b.dataset.view)));
function switchView(view){for(const key of ['journey','week','settings'])$('#'+key+'-view').classList.toggle('hidden',key!==view);$$('.nav-item').forEach(b=>b.classList.toggle('active',b.dataset.view===view));if(view==='week')renderWeek();if(view==='settings')fillForm();document.body.dataset.screen=view;window.scrollTo({top:0,behavior:'instant'});}
$('#close-modal').onclick=()=>modal.close();modal.addEventListener('click',e=>{if(e.target===modal){const r=modal.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)modal.close();}});
const scenarioChips={normal:'Ordinary morning',disruption:'Signal fault',minor:'Small delay',rain:'Heavy rain',planned:'Planned works'};
const alertChips={publicBus:{label:'Free bus boarding',caption:'A simulated LTA alert: East–West Line disruption at Paya Lebar, Aljunied and Kallang, with free public bus boarding.'},shuttle:{label:'Free MRT shuttle',caption:'A simulated LTA alert: East–West Line disruption at Paya Lebar, Aljunied and Kallang, with a free MRT shuttle between them.'}};
function renderScenarioChips(){const host=$('#scenario-chips');if(!host.children.length)host.innerHTML=`<button type="button" class="scenario-chip live-chip" data-live>● Live now</button><span class="chip-divider" aria-hidden="true"></span><span class="chip-group" role="group" aria-labelledby="demo-chips-label"><span class="chip-group-label" id="demo-chips-label">Demo</span>${Object.entries(scenarioChips).map(([key,label])=>`<button type="button" class="scenario-chip" data-scenario="${key}">${label}</button>`).join('')}${Object.entries(alertChips).map(([key,{label}])=>`<button type="button" class="scenario-chip" data-alert="${key}">${label}</button>`).join('')}</span>`;
 host.querySelector('[data-live]').setAttribute('aria-pressed',String(mode==='live'));host.querySelectorAll('[data-scenario]').forEach(chip=>chip.setAttribute('aria-pressed',String(mode==='demo'&&!demoAlert&&chip.dataset.scenario===state.scenario)));host.querySelectorAll('[data-alert]').forEach(chip=>chip.setAttribute('aria-pressed',String(mode==='demo'&&demoAlert===chip.dataset.alert)));
 $('#scenario-caption').textContent=mode==='live'?'Live LTA alerts and crowding for your trip. Travel times are estimates.':demoAlert?alertChips[demoAlert].caption:checkedMode?'Showing the route from a simulated alert check.':scenarios[state.scenario]?.description||'';}
function showLive(){if(mode==='live')return;setMode('live');render();toast('Showing live LTA conditions.');}
$('#scenario-chips').addEventListener('click',event=>{const chip=event.target.closest('[data-live],[data-scenario],[data-alert]');if(!chip)return;if(chip.hasAttribute('data-live'))return showLive();
 if(chip.dataset.alert){if(!Object.hasOwn(alertChips,chip.dataset.alert))return;useDemo(chip.dataset.alert);render();toast(`Showing: ${alertChips[demoAlert].label} (simulated)`);return;}
 if(!Object.hasOwn(scenarios,chip.dataset.scenario))return;useDemo();state.scenario=chip.dataset.scenario;save();render();toast(`Showing: ${scenarios[state.scenario].name} (simulated)`);});
$('#dismiss-demo').onclick=()=>{demoDismissed=true;$('#demo-banner').classList.add('hidden');try{localStorage.setItem('margin-demo-dismissed','1');}catch{}};
// The header pill mirrors the mode and switches it; Data & transparency stays in the footer.
$('#demo-info').onclick=()=>{if(mode==='demo')return showLive();if(!demoAlert&&state.scenario==='normal')state.scenario='disruption';setMode('demo');save();render();toast(`Demo mode: ${demoAlert?alertChips[demoAlert].label:scenarios[state.scenario].name} (simulated)`);};
$('#use-own-trip').onclick=()=>chooseLocation('origin');
$('#modal-content').addEventListener('click',e=>{if(e.target.closest('#refresh-weather'))refreshWeather();});
$('#why-button').onclick=()=>{const r=plan.best;showModal('A little buffer changes everything.',`<p>We rank the available journeys using the slower end of their estimated arrival range, then account for crowding and your preferences.</p><div class="explanation-row"><span>Your arrival deadline</span><strong>${state.deadline}</strong></div><div class="explanation-row"><span>Usual route, cautious arrival</span><strong>${formatTime(plan.usual.arrival)}</strong></div><div class="explanation-row"><span>Recommended, cautious arrival</span><strong>${formatTime(r.arrival)}</strong></div><div class="explanation-row"><span>Your remaining buffer</span><strong>${r.buffer} minutes</strong></div><p>${plan.notice} Alerts trigger below your ${state.threshold}-minute buffer threshold. We keep your usual route when it is safe and within five minutes of the best option.</p>${badge('est','Estimate · rule-based')}`);};
$('#settings-form').onsubmit=e=>{e.preventDefault();checkedMode=null;state.departure=$('#departure').value;state.threshold=Number($('#threshold').value);state.comfort=$('#comfort').checked;state.priority=$('#priority').value;state.walkBreak=Number($('#walkBreak').value);state.large=$('#large-text').checked;const active=routines.find(item=>item.id===activeRoutineId);active.name=$('#routine-name').value.trim();active.enabled=$('#routine-enabled').checked;active.weekdays=$$('[data-weekday]:checked').map(box=>Number(box.dataset.weekday));if(!validWeekdays(active.weekdays)){toast('Choose at least one active weekday.');return;}personalised=true;save();fillForm();render();toast('Routine schedule saved on this device.');};
$('#routine-list').onclick=event=>{const button=event.target.closest('[data-routine-id]');if(!button)return;save();const routine=routines.find(item=>item.id===button.dataset.routineId);if(!routine)return;activeRoutineId=routine.id;state={...defaults,...routine.state};gpsFix=null;addresses={origin:null,destination:null};accessLegs={};checkedMode=null;save();fillForm();render();toast(`${routine.name} selected.`);};
$('#add-routine').onclick=()=>{personalised=true;save();const id=`routine-${Date.now()}`;routines.push({id,name:`Routine ${routines.length+1}`,enabled:true,weekdays:[1,2,3,4,5],state:{...state}});activeRoutineId=id;state={...state};save();fillForm();toast('New routine added. Edit its journey and schedule.');};
$('#delete-routine').onclick=()=>{if(routines.length===1)return;const index=routines.findIndex(item=>item.id===activeRoutineId);routines.splice(index,1);const next=routines[Math.max(0,index-1)];activeRoutineId=next.id;state={...defaults,...next.state};gpsFix=null;addresses={origin:null,destination:null};accessLegs={};checkedMode=null;save();fillForm();render();toast('Routine deleted.');};
$('#clear-data').onclick=()=>{try{localStorage.removeItem('margin-routine');localStorage.removeItem('margin-routines');localStorage.removeItem('margin-active-trip');localStorage.removeItem('margin-demo-dismissed');localStorage.removeItem('margin-mode');localStorage.removeItem('margin-demo-alert');}catch{}personalised=false;demoDismissed=false;mode='live';demoAlert=null;state={...defaults};activeRoutineId='routine-1';routines=[{id:activeRoutineId,name:'Work commute',enabled:true,weekdays:[1,2,3,4,5],state:{...state}}];gpsFix=null;addresses={origin:null,destination:null};accessLegs={};checkedMode=null;save();fillForm();render();toast('Your saved routines and trip have been cleared.');};
$('#access-checklist').onchange=event=>{const box=event.target.closest('[data-access-check]');if(!box)return;let saved={};try{saved=JSON.parse(localStorage.getItem(accessKey())||'{}');saved[box.dataset.accessCheck]=box.checked;localStorage.setItem(accessKey(),JSON.stringify(saved));}catch{}renderAccessChecklist();};
$('#reset-access-checks').onclick=()=>{try{localStorage.removeItem(accessKey());}catch{}renderAccessChecklist();toast('Physical checks reset for this routine.');};
$('#enable-notifications').onclick=async()=>{if(!('Notification'in window)||!('serviceWorker'in navigator)){toast('Notifications are unavailable in this browser.');return;}const permission=await Notification.requestPermission();if(permission==='granted'){const registration=await navigator.serviceWorker.ready;try{await registration.periodicSync?.register('margin-disruption-check',{minInterval:15*60*1000});}catch{}await registration.showNotification('Margin alerts enabled',{body:'We will flag LTA train disruptions when supported background checks run.',icon:'/icon-192.png',tag:'margin-test'});}renderNotificationStatus();};
$('#test-notification').onclick=async()=>{if(Notification.permission!=='granted')return;const registration=await navigator.serviceWorker.ready;await registration.showNotification('Margin test alert',{body:`${places[state.origin].name} → ${places[state.destination].name} is ready.`,icon:'/icon-192.png',tag:'margin-test'});};
$('#weather-info').onclick=()=>showModal('Check the sky before you go.',`<p>${mode==='live'?'Live mode doesn’t adjust journeys for weather yet.':`The journey currently uses <strong>${plan.event.rain?'rainy':'dry'} simulated conditions</strong>.`} You can check the latest public forecast for Tampines.</p><button class="primary-button" id="refresh-weather">Fetch current NEA forecast ↗</button><div id="weather-result"></div>`,'WEATHER · SOURCE CHECK');
async function refreshWeather(){const b=$('#refresh-weather'),out=$('#weather-result');b.disabled=true;out.innerHTML='<p>Checking data.gov.sg…</p>';try{const r=await fetch('https://api-open.data.gov.sg/v2/real-time/api/two-hr-forecast',{signal:AbortSignal.timeout(10000)});if(!r.ok)throw Error();const data=await r.json();const item=data.data?.items?.[0];const forecast=item?.forecasts?.find(x=>x.area==='Tampines');if(!forecast)throw Error();out.innerHTML=`${badge('live','Live · NEA forecast')}<p><strong>Tampines: ${escape(forecast.forecast)}</strong><br>Issued: ${escape(checkedTime(item.timestamp)||item.timestamp)} SGT<br>Valid: ${escape(item.valid_period?.text||`${checkedTime(item.valid_period?.start)} to ${checkedTime(item.valid_period?.end)}`)}</p><p>Shown separately so real weather is never mixed with simulated transport conditions.</p>`;}catch{out.innerHTML='<p>Current weather is unavailable. No live forecast has been assumed.</p>';}finally{b.disabled=false;}}
function renderWeek(){const tomorrow=new Date(Date.now()+86400000),weekday=tomorrow.getDay()||7,active=scheduledRoutines(routines,weekday);$('#week-content').innerHTML=`<article class="week-card">${badge('sim','Simulated · tomorrow')}<h3>EWL frequency reduced, 07:00–09:00</h3><p>Preview how this work window would affect a scheduled routine. Unaffected routes receive no disruption penalty.</p>${active.length?active.map(item=>`<button class="primary-button" data-preview-routine="${escape(item.id)}">Check ${escape(item.name)} <span>↗</span></button>`).join(''):'<p>No enabled routine is scheduled for tomorrow.</p>'}</article><article class="week-card"><h3>Your day-before check</h3><p>${active.length} enabled routine${active.length===1?'':'s'} match tomorrow. Checks run when you open this view; background notifications are not enabled.</p></article>`;$$('[data-preview-routine]').forEach(button=>button.onclick=()=>{save();const routine=routines.find(item=>item.id===button.dataset.previewRoutine);activeRoutineId=routine.id;useDemo();state={...defaults,...routine.state,scenario:'planned'};save();fillForm();render();switchView('journey');toast(`${routine.name} planned-works replay loaded.`);});}
$('#sources-button').onclick=()=>showModal('Clear about what we know.',`<p><strong>Network:</strong> ${Object.keys(places).length} stations across six MRT lines and three LRT networks, including the Changi Airport branch. Station coordinates come from LTA/URA open data via Wu Tingfeng’s station dataset. Topology follows LTA’s system map, checked ${metadata.checked}, including Circle Line 6.</p><p><strong>Route estimates:</strong> connected rail paths are computed locally. Travel times use distance-based assumptions, a 3-minute first-train wait and 5 minutes per transfer. Applicable LTA observations and forecasts are labelled on route cards; fallback crowding and route incidents remain labelled replays. Last-train times and LRT direction-specific schedules are not modelled.</p><p><strong>Walking:</strong> address search uses OneMap. Walking paths use OneMap when authorized and otherwise openrouteservice with OpenStreetMap data. Provider routes are checked for endpoint proximity, geometry, distance and duration, but do not prove step-free access, shelter or current pavement conditions. GPS-only station choices remain straight-line estimates.</p><p><strong>Privacy:</strong> GPS is requested only when you tap Use current location. Coordinates stay in memory for this page session, are not saved, and disappear on reload. Address coordinates are sent through the server only when you explicitly request walking directions.</p><p><strong>Map:</strong> OpenStreetMap road extract covers eastern/central Singapore. The island-wide rail overlay connects station coordinates schematically; it is not track geometry. Routes and map work offline once cached.</p><p><a href="https://github.com/elliotwutingfeng/singapore_train_station_coordinates" target="_blank" rel="noopener">Station dataset ↗</a> · <a href="https://openrouteservice.org/" target="_blank" rel="noopener">openrouteservice ↗</a> · <a href="https://data.gov.sg/open-data-licence" target="_blank" rel="noopener">Singapore Open Data Licence ↗</a> · <a href="https://www.openstreetmap.org/copyright" target="_blank" rel="noopener">OSM attribution ↗</a></p>`,'DATA & TRANSPARENCY');
function setZoom(value){zoom=Math.max(1,Math.min(2.5,value));const w=900/zoom,h=610/zoom;$('#route-map').setAttribute('viewBox',`${(900-w)/2} ${(610-h)/2} ${w} ${h}`);}$('#zoom-in').onclick=()=>setZoom(zoom+.25);$('#zoom-out').onclick=()=>setZoom(zoom-.25);$('#map-reset').onclick=()=>setZoom(1);
function connection(){$('#offline-banner').classList.toggle('hidden',navigator.onLine);}window.addEventListener('online',connection);window.addEventListener('offline',connection);
// Phone bottom bar: a glanceable summary of the selected route; tapping it opens the step list (no walkthrough to click through).
function renderBar(r){const loading=needsCheck()&&!checkedMode,t=tripSummary(plan,r,{departure:state.departure,deadline:state.deadline,threshold:state.threshold}),verdict=$('#bar-verdict');$('#bar-times').textContent=loading?`Leave ${state.departure} · checking…`:`Leave ${t.leave} · Arrive ${t.latest}`;verdict.dataset.tone=loading?'wait':t.tone;verdict.textContent=loading?'Checking live conditions…':`${{ok:'✓',tight:'!',late:'✕'}[t.tone]} ${t.spare}`;$('#journey-action').setAttribute('aria-label',loading?'Checking live conditions. Show journey steps':`Leave ${t.leave}, arrive ${t.latest}, ${t.spare}. Show journey steps`);}
function renderMobileSummary(){const r=currentRoute();$('#origin-name').textContent=addresses.origin?.label||(gpsFix?`Current location → ${places[state.origin].name}`:places[state.origin].name);$('#destination-name').textContent=addresses.destination?.label||places[state.destination].name;$('#commute-summary').textContent=`${places[state.origin].station} → ${places[state.destination].station}`;$('#commute-time').textContent=`Leave ${state.departure} · arrive by ${state.deadline}`;renderBar(r);$('#example-note').classList.toggle('hidden',personalised);$('#routine-example-note').classList.toggle('hidden',personalised);}
function showMap(show){document.body.dataset.map=String(show);$('#show-plan').setAttribute('aria-pressed',String(!show));$('#show-map').setAttribute('aria-pressed',String(show));}
$('#show-plan').onclick=()=>showMap(false);$('#show-map').onclick=()=>showMap(true);$('#journey-action').onclick=()=>{showMap(true);$('.trip-preview').scrollIntoView({block:'start'});};
let installPrompt=null;window.addEventListener('beforeinstallprompt',event=>{event.preventDefault();installPrompt=event;});
function recentStations(){try{const ids=JSON.parse(localStorage.getItem('margin-recent-stations')||'[]');return Array.isArray(ids)?ids.filter(id=>Object.hasOwn(places,id)):[];}catch{return [];}}
function rememberStation(id){try{localStorage.setItem('margin-recent-stations',JSON.stringify([id,...recentStations().filter(item=>item!==id)].slice(0,5)));}catch{}}
let addressTimer,addressRequest=0;
function chooseLocation(field){pickerField=field;gpsCandidate=null;gpsRequest++;clearTimeout(addressTimer);addressRequest++;showModal(field==='origin'?'Where are you starting?':'Where are you going?',`${field==='origin'?'<button type="button" id="use-gps" class="gps-button"><span aria-hidden="true">⌖</span><span><strong>Use current location</strong><small>Find nearby stations using GPS</small></span></button><div id="gps-status" role="status" aria-live="polite"></div>':''}<label for="place-search" class="picker-label">Search stations, addresses or postal codes</label><input id="place-search" type="search" maxlength="100" placeholder="e.g. Tampines, NE17 or 048616" autocomplete="off"><div id="station-results" class="location-options" aria-live="polite"></div><div id="address-results" aria-live="polite"></div>`,'SINGAPORE LOCATIONS');renderStationResults();$('#place-search').oninput=onPlaceSearch;$('#place-search').onkeydown=event=>{if(event.key!=='Enter')return;event.preventDefault();clearTimeout(addressTimer);searchAddresses($('#place-search').value.trim());};if(field==='origin')$('#use-gps').onclick=requestGps;}
// One box: stations filter instantly on this device; addresses and postal codes go to OneMap after a short pause.
function onPlaceSearch(){renderStationResults();clearTimeout(addressTimer);const query=$('#place-search').value.trim();if(query.length<3){addressRequest++;$('#address-results').innerHTML='';return;}addressTimer=setTimeout(()=>searchAddresses(query),450);}
async function searchAddresses(query){const out=$('#address-results');if(!out||query.length<2)return;const request=++addressRequest;out.innerHTML='<p class="picker-group">Addresses</p><p class="picker-hint">Searching OneMap…</p>';try{const response=await fetch(`/api/locations/search?q=${encodeURIComponent(query)}`,{signal:AbortSignal.timeout(10000),cache:'no-store'});const data=await response.json();if(request!==addressRequest||!out.isConnected)return;if(!response.ok||data.source!=='onemap')throw Error();out._results=data.results;out.innerHTML=`<p class="picker-group">Addresses</p>${data.results.length?`<div class="address-options">${data.results.map((item,index)=>`<button type="button" class="location-option" data-address-index="${index}"><span><strong>${escape(item.label)}</strong><small>Verified by OneMap</small></span><span aria-hidden="true">→</span></button>`).join('')}</div>`:'<p class="picker-hint">No matching Singapore address.</p>'}`;}catch{if(request!==addressRequest||!out.isConnected)return;out.innerHTML='<p class="picker-group">Addresses</p><p class="picker-hint">Address search is unavailable right now. You can still choose a station.</p>';}}
async function walkingRoute(start,end){const params=new URLSearchParams({startLon:start[0],startLat:start[1],endLon:end[0],endLat:end[1]});const response=await fetch(`/api/walking-route?${params}`,{signal:AbortSignal.timeout(15000),cache:'no-store'});const data=await response.json();if(!response.ok||!['onemap','openrouteservice'].includes(data.source))throw Error(data.message||data.error||'Walking route unavailable.');return data;}
const searchable=value=>value.toLowerCase().replace(/[–—-]/g,' ');
function stationOption(p){return `<button type="button" class="location-option" data-location="${p.id}" data-field="${pickerField}" aria-pressed="${state[pickerField]===p.id}"><span><strong>${escape(p.name)}</strong><small>${p.code} · ${p.lines.join(' / ')}</small></span><span aria-hidden="true">${state[pickerField]===p.id?'✓':'→'}</span></button>`;}
function renderStationResults(){const query=searchable($('#place-search').value.trim()),host=$('#station-results');const matches=Object.values(places).filter(p=>searchable(`${p.name} ${p.code} ${p.lines.join(' ')} ${p.lines.map(l=>lines[l]).join(' ')}`).includes(query)).sort((a,b)=>a.name.localeCompare(b.name));if(!query){const recent=recentStations().map(id=>places[id]);host.innerHTML=`${recent.length?`<p class="picker-group">Recent</p>${recent.map(stationOption).join('')}`:''}<p class="picker-group">All stations (${matches.length})</p>${matches.map(stationOption).join('')}`;return;}host.innerHTML=matches.length?`<p class="picker-group">Stations (${matches.length})</p>${matches.map(stationOption).join('')}`:'<p class="picker-group">Stations</p><p class="picker-hint">No matching station name or code.</p>';}
$('#choose-origin').onclick=()=>chooseLocation('origin');$('#choose-destination').onclick=()=>chooseLocation('destination');
$('#modal-content').addEventListener('click',async event=>{const option=event.target.closest('[data-location]');if(option){const field=option.dataset.field,key=option.dataset.location;if(!['origin','destination'].includes(field)||!Object.hasOwn(places,key))return;const next={...state,[field]:key};try{planJourney(next);if(field==='origin')gpsFix=null;addresses[field]=null;delete accessLegs[field];checkedMode=null;state=next;personalised=true;rememberStation(key);save();fillForm();render();modal.close();toast(`${field==='origin'?'Starting station':'Destination'} updated. Routes recalculated.`);}catch(error){toast(error.message);}}
 const addressButton=event.target.closest('[data-address-index]');if(addressButton){const out=$('#address-results'),item=out?._results?.[Number(addressButton.dataset.addressIndex)];if(!item)return;addressButton.disabled=true;out.setAttribute('aria-busy','true');try{const nearest=nearestStations(item.coord,places,1)[0],field=pickerField;const walk=field==='origin'?await walkingRoute(item.coord,nearest.coord):await walkingRoute(nearest.coord,item.coord);state={...state,[field]:nearest.id};addresses[field]=item;accessLegs[field]=walk;if(field==='origin')gpsFix=null;checkedMode=null;personalised=true;save();fillForm();render();modal.close();toast(`${field==='origin'?'Start':'Destination'} connected to ${nearest.name} by a verified walk.`);}catch(error){toast(error.message);}finally{out?.setAttribute('aria-busy','false');}}
 const nearby=event.target.closest('[data-gps-station]');if(nearby&&gpsCandidate){const key=nearby.dataset.gpsStation,next={...state,origin:key};try{planJourney({...next,originLocation:gpsCandidate});gpsFix={coord:gpsCandidate.coord,accuracy:gpsCandidate.accuracy,timestamp:gpsCandidate.timestamp};addresses.origin=null;delete accessLegs.origin;checkedMode=null;state=next;personalised=true;save();fillForm();render();modal.close();toast(`GPS start set via ${places[key].name}.`);}catch(error){toast(error.message);}}});
function requestGps(){const out=$('#gps-status'),button=$('#use-gps');if(!navigator.geolocation){out.textContent='GPS is unavailable in this browser. Search for a station below.';return;}if(!window.isSecureContext){out.textContent='Location requires HTTPS. Open the published Margin link on your phone.';return;}const request=++gpsRequest;button.disabled=true;out.textContent='Finding your location… Allow access when your browser asks.';navigator.geolocation.getCurrentPosition(position=>{if(request!==gpsRequest||!modal.open||!$('#gps-status'))return;button.disabled=false;try{gpsCandidate=validatePosition(position,places);out.innerHTML=`<p>Location accuracy: about ${Math.round(gpsCandidate.accuracy)} m. Choose your boarding station. Walking estimates are approximate.</p>${gpsCandidate.nearby.filter(s=>s.distance<=3).map(s=>`<button class="location-option" type="button" data-gps-station="${s.id}"><span><strong>${escape(s.name)}</strong><small>${s.distance.toFixed(2)} km away · about ${Math.max(2,Math.ceil(s.distance*1.3/.075))} min walk</small></span><span aria-hidden="true">→</span></button>`).join('')}`;}catch(error){out.textContent=error.message;}},error=>{if(request!==gpsRequest||!modal.open||!$('#gps-status'))return;button.disabled=false;out.textContent=gpsError(error);},{enableHighAccuracy:true,timeout:12000,maximumAge:60000});}
modal.addEventListener('close',()=>{gpsRequest++;gpsCandidate=null;});
$('#edit-arrival').onclick=()=>{showModal('When do you need to arrive?',`<form id="arrival-form"><label for="arrival-time">Arrive by</label><input id="arrival-time" type="time" value="${state.deadline}" required><button type="submit" class="primary-button">Update arrival time →</button></form>`,'YOUR ARRIVAL DEADLINE');$('#arrival-form').onsubmit=event=>{event.preventDefault();const next={...state,deadline:$('#arrival-time').value};planJourney(next);checkedMode=null;state=next;personalised=true;save();fillForm();render();modal.close();toast('Arrival time updated.');};};
$('#install-app').onclick=async()=>{if(installPrompt){await installPrompt.prompt();const result=await installPrompt.userChoice;installPrompt=null;if(result.outcome==='accepted')toast('Margin has been added to your home screen.');return;}showModal('Your commute, one tap away.','<p><strong>iPhone:</strong> open Margin in Safari, tap Share, then choose Add to Home Screen.</p><p><strong>Android:</strong> open Margin in Chrome, open the menu, then choose Install app or Add to Home screen.</p><p>Use the published HTTPS link on your phone. Margin opens as a standalone web app where your browser supports it.</p>','ADD TO HOME SCREEN');};
for(const field of ['origin','destination'])$('#'+field).innerHTML=Object.values(places).sort((a,b)=>a.name.localeCompare(b.name)).map(p=>`<option value="${p.id}">${escape(p.name)}</option>`).join('');fillForm();render();loadMap();connection();if('serviceWorker'in navigator)navigator.serviceWorker.register('/sw.js').catch(()=>{});
if(document.modelContext?.registerTool){const lifecycle=new AbortController();try{Promise.resolve(document.modelContext.registerTool({name:'configure_commute_replay',title:'Configure commute replay',description:'Set a supported demo corridor and replay scenario, recompute routes, and save the routine on this device. Does not fetch live transport data.',inputSchema:{type:'object',properties:{origin:{type:'string',enum:Object.keys(places)},destination:{type:'string',enum:Object.keys(places)},scenario:{type:'string',enum:Object.keys(scenarios)}},required:['origin','destination','scenario'],additionalProperties:false},annotations:{readOnlyHint:false,untrustedContentHint:false},execute(input){if(!input||Object.keys(input).some(k=>!['origin','destination','scenario'].includes(k))||!Object.hasOwn(places,input.origin)||!Object.hasOwn(places,input.destination)||!Object.hasOwn(scenarios,input.scenario))throw new Error('Invalid supported corridor or replay scenario.');const next={...state,...input};planJourney(next);state=next;useDemo();gpsFix=null;save();fillForm();render();switchView('journey');return {scenario:state.scenario,recommendedRoute:plan.best.id,arrival:formatTime(plan.best.arrival),bufferMinutes:plan.best.buffer,dataMode:'synthetic transport replay'};}},{signal:lifecycle.signal})).catch(()=>{});}catch{}window.addEventListener('pagehide',()=>lifecycle.abort(),{once:true});}

$('#departure-button').onclick=()=>showDepartureOptions();
function showDepartureOptions(){
 const start=Number(state.departure.slice(0,2))*60+Number(state.departure.slice(3)),rank={low:0,medium:1,high:2};
 const options=[-30,-15,0,15,30].filter(offset=>start+offset>=0&&start+offset<1440).map(offset=>{const departure=formatTime(start+offset),p=planJourney({...plannedState(),departure,originLocation:gpsFix});const r=p.best;return {departure,r,buffer:plan.due-(start+offset+r.max)};});
 showModal('A little flexibility goes a long way.',`<p>Compare departures around ${state.departure}. Your arrival deadline stays ${state.deadline}. Choose one to update your plan.</p>${badge('est','Estimated crowd model')}<p>On ordinary days, this model assumes busier EWL, NSL and NEL trains at 07:30–09:00 and 17:00–19:00. Shifting travel could spread demand; this does not predict a seat.</p><div class="departure-options">${options.map(o=>`<button class="location-option" data-departure="${o.departure}" ${o.buffer<0?'disabled':''}><span><strong>${o.departure}${o.departure===state.departure?' · current':''}</strong><small>${o.r.min}–${o.r.max} min · ${['Lower','Moderate','Higher'][rank[o.r.crowd]]} modelled crowding</small><small>${o.buffer<0?`${-o.buffer} min after deadline`:`${o.buffer} min arrival buffer`}</small></span><span aria-hidden="true">${o.buffer<0?'—':'→'}</span></button>`).join('')}</div><p>Options missing your deadline cannot be selected. Estimates exclude operating hours; check actual service before travelling.</p>`,'YOUR DEPARTURE WINDOW');
}
$('#modal-content').addEventListener('click',event=>{const button=event.target.closest('[data-departure]');if(!button)return;checkedMode=null;state.departure=button.dataset.departure;personalised=true;save();fillForm();render();modal.close();toast('Departure updated. Your arrival deadline is unchanged.');});
